    # -- write -------------------------------------------------------------

    def write(self, stage, ordinal: int) -> None:
        """Upsert every prim in one operation. Seal ``ordinal`` afterwards before attaching."""
        if self._type is None:
            raise ValueError('no prim type defined')
        applied = {s.split(':', 1)[0] for s in self._schemas}  # base ids; multi-apply entries are qualified
        for api in self._schemas:
            base, _, inst = api.partition(':')
            for req in API_REQUIRES[base]:
                # a multi-apply API extending another multi-apply API needs the same instance
                if inst and req in API_MULTI_APPLY:
                    if f'{req}:{inst}' not in self._schemas:
                        raise ValueError(f'{api} requires {req}:{inst} on the same prim')
                elif req not in applied:
                    raise ValueError(f'{api} requires {req} on the same prim')
        # Structural columns last so the schema list reflects every enabled group. They are built
        # per write on top of the retained payload, so a retry or a second write sends the full
        # prim again (as the C++ builder does) instead of only the structural columns.
        payload_writes, payload_keep = list(self._writes), list(self._keep)
        try:
            type_id = self._paths.intern_token(self._type).raw_id
            self._add('usd-prim-type', [type_id] * self._n, 'uint64', 1, None)
            if self._schemas:  # USD population omits the column on a prim with no applied schemas
                ids = [self._paths.intern_token(s).raw_id for s in self._schemas]
                self._add_ids('usd-schemas', [ids] * self._n, None)
            # The path list is caller-owned: releasing the query does not release it.
            path_list = self._paths.create_path_list_from_strings(self._prim_paths)
            try:
                query = stage.query_from_path_list(path_list)
                try:
                    stage.write_attributes(query, self._writes, ordinal).wait()
                finally:
                    stage.release_query(query).wait()
            finally:
                self._paths.destroy_path_list(path_list)
        finally:
            self._writes, self._keep = payload_writes, payload_keep


