    p35 = P.has_applied_schema('PhysicsRigidBodyAPI')
    e36 = E.number(5e-05)
    e37 = E.number(10.0)
    e38 = E.divide(e37, e24)
    e39 = E.multiply(e38, e38)
    e40 = E.multiply(e36, e39)
    e41 = E.number(1e-05)
